using System;using System.IO;using System.Linq;using System.Collections;using System.Collections.Generic;using UnityEngine;using UnityEditor;using CatGunner.Runtime;
public static class PreviewDegreeFx {
 static string Dir=>Path.GetFullPath(Application.dataPath+"/../../../art/reskin/penguin-expedition/degree-fx-v1");
 static GameClient Client()=>UnityEngine.Object.FindAnyObjectByType<GameClient>(FindObjectsInactive.Include);
 public static string Prepare(){if(Application.isPlaying||Client().gameObject.scene.isDirty)throw new Exception("Saved EditMode required");var c=Client();File.WriteAllText(Dir+"/preview-state.json",Newtonsoft.Json.JsonConvert.SerializeObject(new{c.Persist,c.SaveFolderOverride,host=SessionState.GetString("CatGunner.Recovery.TestHostFolder","")}));c.Persist=false;c.SaveFolderOverride=Path.Combine(Application.temporaryCachePath,"PenguinPreview-DegreeFx-"+Guid.NewGuid().ToString("N"));SessionState.SetString("CatGunner.Recovery.TestHostFolder",c.SaveFolderOverride);return c.SaveFolderOverride;}
 public static string Restore(){if(Application.isPlaying)throw new Exception("EditMode required");var d=Newtonsoft.Json.Linq.JObject.Parse(File.ReadAllText(Dir+"/preview-state.json"));var c=Client();c.Persist=(bool)d["Persist"];c.SaveFolderOverride=d["SaveFolderOverride"].Type==Newtonsoft.Json.Linq.JTokenType.Null?null:(string)d["SaveFolderOverride"];SessionState.SetString("CatGunner.Recovery.TestHostFolder",(string)d["host"]);return "Original persistence and preview host restored without saving the scene";}
 public static string Capture(){var c=Client();if(!Application.isPlaying||c.Persist||!c.SaveFolderOverride.Contains("PenguinPreview-DegreeFx"))throw new Exception("Isolated Play required");Directory.CreateDirectory(Dir+"/captures");c.StartCoroutine(Run(c));return "Recording live degree emitters and validating native particle contracts";}
 public static object Observe(){if(!Application.isPlaying)throw new Exception("Play required");var c=Client();var fx=c.Hero.transform.Find("Degree_FX").GetComponentsInChildren<ParticleSystem>(true);var records=fx.Select(p=>{var r=p.GetComponent<ParticleSystemRenderer>();string tex=r.sharedMaterial.mainTexture.name;bool correct=p.name=="shadow"?tex=="shadow-rings"&&p.textureSheetAnimation.numTilesX==2&&p.textureSheetAnimation.numTilesY==2&&p.textureSheetAnimation.mode==ParticleSystemAnimationMode.Grid&&r.renderMode==ParticleSystemRenderMode.Mesh&&p.GetComponent<PenguinDegreeGroundRing>()!=null:p.name=="Glow"?tex=="halo":p.name=="FireFlies"?tex=="effects-02":p.name=="Z Degree FX"?tex=="effects-00":true;return new{p.name,parent=p.transform.parent.name,texture=tex,correct,active=p.gameObject.activeInHierarchy,count=p.particleCount,mode=r.renderMode.ToString()};}).ToArray();if(records.Any(r=>!r.correct))throw new Exception("Runtime binding mismatch");Directory.CreateDirectory(Dir+"/captures");File.WriteAllText(Dir+"/runtime-checks.json",Newtonsoft.Json.JsonConvert.SerializeObject(new{source="Read-only observation of user's live PlayMode; no gameplay, save, equipment or emitter changes",records,passed=records.Length},Newtonsoft.Json.Formatting.Indented));c.StartCoroutine(ObserveFrames());return new{passed=records.Length,active=records.Count(r=>r.active)};}
 static IEnumerator ObserveFrames(){for(int i=0;i<12;i++){yield return new WaitForSecondsRealtime(.2f);yield return new WaitForEndOfFrame();var t=ScreenCapture.CaptureScreenshotAsTexture();try{File.WriteAllBytes(Dir+"/captures/live-"+i.ToString("00")+".png",t.EncodeToPNG());}finally{UnityEngine.Object.Destroy(t);}}File.WriteAllText(Dir+"/captures/complete.json","{\"frames\":12,\"source\":\"Actual Game view timed GPU screenshots\"}");}
 static IEnumerator Run(GameClient c){while(!c.ReadyForPlay)yield return null;c.DailyLogin.AutoShow=false;c.DailyLogin.Close();c.Tutorial.SetCleared();yield return new WaitForSeconds(2);
 var root=c.Hero.transform.Find("Degree_FX");if(root==null)throw new Exception("No hero Degree_FX");var fx=root.GetComponentsInChildren<ParticleSystem>(true);var checks=new List<object>();
 foreach(var p in fx){var r=p.GetComponent<ParticleSystemRenderer>();var texture=r.sharedMaterial.mainTexture;bool shadow=p.name=="shadow";bool fire=p.name=="FireFlies";bool glow=p.name=="Glow";bool match=shadow?texture.name=="shadow-rings":fire?texture.name=="effects-02":glow?texture.name=="halo":true;bool shape=!shadow||p.textureSheetAnimation.numTilesX==2&&p.textureSheetAnimation.numTilesY==2&&p.textureSheetAnimation.mode==ParticleSystemAnimationMode.Grid&&r.renderMode==ParticleSystemRenderMode.Mesh&&p.GetComponent<PenguinDegreeGroundRing>()!=null;checks.Add(new{p.name,parent=p.transform.parent.name,texture=texture.name,match,shape,mode=r.renderMode.ToString(),tiles=new[]{p.textureSheetAnimation.numTilesX,p.textureSheetAnimation.numTilesY},trails=p.trails.enabled});if(!match||!shape)throw new Exception("Wrong runtime binding "+p.name);}
 // Activate existing authored emitters only inside the isolated visual fixture.
 var states=Enumerable.Range(0,root.childCount).Select(i=>root.GetChild(i)).ToDictionary(t=>t,t=>t.gameObject.activeSelf);
 foreach(int degree in new[]{4,7,10}){
 foreach(var pair in states)pair.Key.gameObject.SetActive(pair.Key.name==degree.ToString());root.gameObject.SetActive(true);var group=root.Find(degree.ToString());if(group==null)continue;foreach(var p in group.GetComponentsInChildren<ParticleSystem>(true)){p.gameObject.SetActive(true);p.Play(false);}
 for(int frame=0;frame<5;frame++){yield return new WaitForSeconds(.35f);yield return new WaitForEndOfFrame();ScreenCapture.CaptureScreenshot(Dir+"/captures/degree-"+degree+"-"+frame+".png");yield return null;}
 }
 foreach(var pair in states)pair.Key.gameObject.SetActive(pair.Value);
 File.WriteAllText(Dir+"/runtime-checks.json",Newtonsoft.Json.JsonConvert.SerializeObject(new{source="Actual Unity PlayMode native degree emitters, five timed Game-view frames per grade",save=c.SaveFolderOverride,checks,complete=true},Newtonsoft.Json.Formatting.Indented));
 }
}
